using System;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Spatial;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの縄張り評価システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyTerritoryTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 48;

        /// <summary>
        /// 浮動小数点数の比較許容誤差。
        /// </summary>
        private const float Tolerance = 0.0001f;

        /// <summary>
        /// テスト用の縄張り中心座標。
        /// </summary>
        private static readonly Vector2Int Origin =
            new Vector2Int(1, 1);

        /// <summary>
        /// テスト用ステージ管理インスタンス。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext context;

        /// <summary>
        /// テスト対象の縄張り評価システム。
        /// </summary>
        private MazeEnemyTerritory territory;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestDistance();

                Prepare();
                TestEvaluation();

                Prepare();
                TestParameters();

                Prepare();
                TestCache();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyTerritory テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を初期化する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "テスト用ステージの生成に失敗しました。");
            }

            if (stageManager.Map.Width < 10 ||
                stageManager.Map.Height < 5)
            {
                throw new InvalidOperationException(
                    "テスト用グリッドは10×5以上が必要です。");
            }

            // 固定された通行条件でテストを行う。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            movementObject =
                new GameObject("TerritoryTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                Origin);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius,
                4f);

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                0.8f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "TerritoryTest",
                    parameters);

            context = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                Origin);

            territory = new MazeEnemyTerritory(context);
        }

        /// <summary>
        /// 初期状態と引数検証を確認する。
        /// </summary>
        private void TestInitialization()
        {
            bool contextPassed =
                ReferenceEquals(territory.Context, context);
            Debug.Assert(contextPassed, "コンテキスト参照", this);
            Check(contextPassed, "コンテキスト参照");

            bool validPassed =
                territory.IsValid && !territory.IsDisposed;
            Debug.Assert(validPassed, "初期有効状態", this);
            Check(validPassed, "初期有効状態");

            bool centerPassed =
                territory.Center == Origin;
            Debug.Assert(centerPassed, "初期縄張り中心", this);
            Check(centerPassed, "初期縄張り中心");

            bool radiusPassed =
                Approximately(territory.Radius, 4f);
            Debug.Assert(radiusPassed, "初期縄張り半径", this);
            Check(radiusPassed, "初期縄張り半径");

            bool territorialityPassed =
                Approximately(territory.Territoriality, 0.8f);
            Debug.Assert(territorialityPassed, "初期縄張り意識", this);
            Check(territorialityPassed, "初期縄張り意識");

            bool lazyPassed =
                territory.IsDirty &&
                territory.RecalculationCount == 0;
            Debug.Assert(lazyPassed, "初期遅延計算状態", this);
            Check(lazyPassed, "初期遅延計算状態");

            bool nullPassed = false;

            try
            {
                new MazeEnemyTerritory(null);
            }
            catch (ArgumentNullException)
            {
                nullPassed = true;
            }

            Debug.Assert(nullPassed, "nullコンテキストの拒否", this);
            Check(nullPassed, "nullコンテキストの拒否");

            context.Dispose();

            bool invalidPassed = false;

            try
            {
                new MazeEnemyTerritory(context);
            }
            catch (ArgumentException)
            {
                invalidPassed = true;
            }

            Debug.Assert(invalidPassed, "無効なコンテキストの拒否", this);
            Check(invalidPassed, "無効なコンテキストの拒否");
        }

        /// <summary>
        /// 距離計算と縄張り範囲を確認する。
        /// </summary>
        private void TestDistance()
        {
            bool originPassed =
                territory.GetDistance(Origin) == 0;
            Debug.Assert(originPassed, "中心の距離", this);
            Check(originPassed, "中心の距離");

            bool neighborPassed =
                territory.GetDistance(
                    Origin + Vector2Int.right) == 1;
            Debug.Assert(neighborPassed, "隣接セルの距離", this);
            Check(neighborPassed, "隣接セルの距離");

            bool insidePassed =
                territory.IsInsideTerritory(
                    new Vector2Int(3, 1));
            Debug.Assert(insidePassed, "縄張り内の判定", this);
            Check(insidePassed, "縄張り内の判定");

            bool boundaryPassed =
                territory.IsInsideTerritory(
                    new Vector2Int(5, 1));
            Debug.Assert(boundaryPassed, "縄張り境界の包含", this);
            Check(boundaryPassed, "縄張り境界の包含");

            bool outsidePassed =
                !territory.IsInsideTerritory(
                    new Vector2Int(6, 1));
            Debug.Assert(outsidePassed, "縄張り外の判定", this);
            Check(outsidePassed, "縄張り外の判定");

            bool outOfBoundsPassed =
                territory.GetDistance(
                    new Vector2Int(-1, 0)) == -1;
            Debug.Assert(outOfBoundsPassed, "グリッド外の拒否", this);
            Check(outOfBoundsPassed, "グリッド外の拒否");

            // 直接移動できないように壁を配置する。
            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            bool detourPassed =
                territory.GetDistance(
                    new Vector2Int(3, 1)) == 4;
            Debug.Assert(detourPassed, "壁を迂回した距離", this);
            Check(detourPassed, "壁を迂回した距離");

            bool wallPassed =
                !territory.TryEvaluate(
                    new Vector2Int(2, 1),
                    out var evaluation) &&
                !evaluation.IsValid;
            Debug.Assert(wallPassed, "壁の評価拒否", this);
            Check(wallPassed, "壁の評価拒否");
        }

        /// <summary>
        /// 縄張り評価値の計算を確認する。
        /// </summary>
        private void TestEvaluation()
        {
            bool validPassed =
                territory.TryEvaluate(
                    Origin,
                    out var centerEvaluation) &&
                centerEvaluation.IsValid &&
                centerEvaluation.IsReachable &&
                centerEvaluation.Position == Origin &&
                centerEvaluation.Center == Origin;
            Debug.Assert(validPassed, "評価結果の生成", this);
            Check(validPassed, "評価結果の生成");

            bool insidePassed =
                centerEvaluation.IsInsideTerritory &&
                !centerEvaluation.IsOutsideTerritory &&
                Approximately(
                    centerEvaluation.PreferenceMultiplier, 1f) &&
                Approximately(
                    centerEvaluation.ReturnScore, 0f);
            Debug.Assert(insidePassed, "縄張り内の評価値", this);
            Check(insidePassed, "縄張り内の評価値");

            territory.TryEvaluate(
                new Vector2Int(5, 1),
                out var boundaryEvaluation);

            bool boundaryPassed =
                boundaryEvaluation.IsInsideTerritory &&
                Approximately(
                    boundaryEvaluation.OutsideDistance, 0f) &&
                Approximately(
                    boundaryEvaluation.OutsideRatio, 0f);
            Debug.Assert(boundaryPassed, "縄張り境界の評価値", this);
            Check(boundaryPassed, "縄張り境界の評価値");

            territory.TryEvaluate(
                new Vector2Int(7, 1),
                out var outsideEvaluation);

            bool outsidePassed =
                outsideEvaluation.IsOutsideTerritory &&
                outsideEvaluation.Distance == 6 &&
                Approximately(
                    outsideEvaluation.OutsideDistance, 2f);
            Debug.Assert(outsidePassed, "縄張り逸脱距離", this);
            Check(outsidePassed, "縄張り逸脱距離");

            bool ratioPassed =
                Approximately(
                    outsideEvaluation.OutsideRatio, 0.5f);
            Debug.Assert(ratioPassed, "縄張り逸脱度", this);
            Check(ratioPassed, "縄張り逸脱度");

            bool multiplierPassed =
                Approximately(
                    outsideEvaluation.PreferenceMultiplier, 0.64f);
            Debug.Assert(multiplierPassed, "移動先評価倍率", this);
            Check(multiplierPassed, "移動先評価倍率");

            bool returnPassed =
                Approximately(
                    outsideEvaluation.ReturnScore, 0.4f);
            Debug.Assert(returnPassed, "帰還欲求の評価", this);
            Check(returnPassed, "帰還欲求の評価");

            territory.TryEvaluate(
                new Vector2Int(9, 1),
                out var farEvaluation);

            bool saturationPassed =
                Approximately(
                    farEvaluation.OutsideRatio, 1f) &&
                Approximately(
                    farEvaluation.PreferenceMultiplier, 0.28f) &&
                Approximately(
                    farEvaluation.ReturnScore, 0.8f);
            Debug.Assert(saturationPassed, "逸脱度の上限処理", this);
            Check(saturationPassed, "逸脱度の上限処理");
        }

        /// <summary>
        /// パラメーター変更への対応を確認する。
        /// </summary>
        private void TestParameters()
        {
            Vector2Int target = new Vector2Int(7, 1);

            territory.Refresh();

            long initialCount =
                territory.RecalculationCount;

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                0f);

            bool zeroPassed =
                Approximately(
                    territory.GetPreferenceMultiplier(target),
                    1f) &&
                Approximately(
                    territory.GetReturnScore(target),
                    0f);
            Debug.Assert(zeroPassed, "縄張り意識0の評価", this);
            Check(zeroPassed, "縄張り意識0の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                1f);

            bool maximumPassed =
                Approximately(
                    territory.GetPreferenceMultiplier(target),
                    0.55f) &&
                Approximately(
                    territory.GetReturnScore(target),
                    0.5f);
            Debug.Assert(maximumPassed, "縄張り意識最大の評価", this);
            Check(maximumPassed, "縄張り意識最大の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius,
                6f);

            bool radiusPassed =
                territory.IsInsideTerritory(target) &&
                Approximately(
                    territory.GetPreferenceMultiplier(target),
                    1f);
            Debug.Assert(radiusPassed, "縄張り半径変更の反映", this);
            Check(radiusPassed, "縄張り半径変更の反映");

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius,
                0f);

            bool zeroRadiusPassed =
                territory.IsInsideTerritory(Origin) &&
                !territory.IsInsideTerritory(
                    Origin + Vector2Int.right);
            Debug.Assert(zeroRadiusPassed, "半径0の縄張り判定", this);
            Check(zeroRadiusPassed, "半径0の縄張り判定");

            bool minimumMultiplierPassed =
                Approximately(
                    territory.GetPreferenceMultiplier(target),
                    0.1f) &&
                Approximately(
                    territory.GetReturnScore(target),
                    1f);
            Debug.Assert(
                minimumMultiplierPassed,
                "評価倍率の下限維持",
                this);
            Check(
                minimumMultiplierPassed,
                "評価倍率の下限維持");

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius,
                2.5f);

            bool fractionalPassed =
                territory.IsInsideTerritory(
                    new Vector2Int(3, 1)) &&
                !territory.IsInsideTerritory(
                    new Vector2Int(4, 1));
            Debug.Assert(fractionalPassed, "小数半径の判定", this);
            Check(fractionalPassed, "小数半径の判定");

            territory.TryEvaluate(
                target,
                out var previousEvaluation);

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                0.2f);

            territory.TryEvaluate(
                target,
                out var newEvaluation);

            bool snapshotPassed =
                Approximately(
                    previousEvaluation.Territoriality, 1f) &&
                Approximately(
                    newEvaluation.Territoriality, 0.2f);
            Debug.Assert(snapshotPassed, "評価結果の独立性", this);
            Check(snapshotPassed, "評価結果の独立性");

            bool cachePassed =
                territory.RecalculationCount == initialCount &&
                !territory.IsDirty;
            Debug.Assert(cachePassed, "パラメーター変更時のキャッシュ維持", this);
            Check(cachePassed, "パラメーター変更時のキャッシュ維持");
        }

        /// <summary>
        /// 距離マップのキャッシュ管理を確認する。
        /// </summary>
        private void TestCache()
        {
            bool firstPassed =
                territory.Refresh() &&
                territory.RecalculationCount == 1 &&
                !territory.IsDirty;
            Debug.Assert(firstPassed, "初回距離計算", this);
            Check(firstPassed, "初回距離計算");

            territory.Refresh();
            territory.GetDistance(Origin);
            territory.GetReturnScore();

            bool reusePassed =
                territory.RecalculationCount == 1;
            Debug.Assert(reusePassed, "距離マップの再利用", this);
            Check(reusePassed, "距離マップの再利用");

            Vector2Int gemPosition =
                new Vector2Int(2, 2);

            stageManager.Map.SetCell(
                gemPosition,
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            stageManager.Map.SetCell(
                gemPosition,
                MazeCell.CreateFloor());

            bool gemPassed =
                !territory.IsDirty &&
                territory.Refresh() &&
                territory.RecalculationCount == 1;
            Debug.Assert(gemPassed, "宝石変更時の再計算抑制", this);
            Check(gemPassed, "宝石変更時の再計算抑制");

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            stageManager.Map.SetCell(
                new Vector2Int(2, 2),
                MazeCell.CreateWall());

            bool dirtyPassed =
                territory.IsDirty &&
                territory.RecalculationCount == 1;
            Debug.Assert(dirtyPassed, "通行条件変更時の遅延更新", this);
            Check(dirtyPassed, "通行条件変更時の遅延更新");

            bool batchPassed =
                territory.GetDistance(
                    new Vector2Int(3, 1)) == 4 &&
                territory.RecalculationCount == 2 &&
                !territory.IsDirty;
            Debug.Assert(batchPassed, "複数変更の一括再計算", this);
            Check(batchPassed, "複数変更の一括再計算");

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateFloor());

            bool openedPassed =
                territory.GetDistance(
                    new Vector2Int(3, 1)) == 2 &&
                territory.RecalculationCount == 3;
            Debug.Assert(openedPassed, "通路開放後の距離更新", this);
            Check(openedPassed, "通路開放後の距離更新");

            Vector2Int newCenter =
                new Vector2Int(3, 1);

            bool centerChanged =
                context.TrySetTerritoryCenter(newCenter);

            bool centerPassed =
                centerChanged &&
                territory.IsDirty &&
                territory.GetDistance(newCenter) == 0 &&
                territory.GetDistance(Origin) == 2 &&
                territory.RecalculationCount == 4;
            Debug.Assert(centerPassed, "縄張り中心変更の検知", this);
            Check(centerPassed, "縄張り中心変更の検知");

            territory.Invalidate();

            bool invalidatePassed =
                territory.IsDirty &&
                territory.Refresh() &&
                territory.RecalculationCount == 5 &&
                !territory.IsDirty;
            Debug.Assert(invalidatePassed, "明示的なキャッシュ無効化", this);
            Check(invalidatePassed, "明示的なキャッシュ無効化");
        }

        /// <summary>
        /// ライフサイクルと無効状態への対応を確認する。
        /// </summary>
        private void TestLifecycle()
        {
            bool currentPassed =
                territory.TryEvaluateCurrentPosition(
                    out var evaluation) &&
                evaluation.Position == Origin &&
                Approximately(
                    territory.GetReturnScore(), 0f);
            Debug.Assert(currentPassed, "現在位置の評価", this);
            Check(currentPassed, "現在位置の評価");

            bool teleported = movement.TryTeleport(
                new Vector2Int(7, 1));

            bool movedPassed =
                teleported &&
                territory.TryEvaluateCurrentPosition(
                    out var movedEvaluation) &&
                movedEvaluation.Distance == 6 &&
                Approximately(
                    territory.GetReturnScore(), 0.4f);
            Debug.Assert(movedPassed, "移動後の現在位置評価", this);
            Check(movedPassed, "移動後の現在位置評価");

            // 縄張り中心を通行不可能にする。
            stageManager.Map.SetCell(
                Origin,
                MazeCell.CreateWall());

            bool blockedPassed =
                !territory.Refresh() &&
                territory.GetDistance(Origin) == -1 &&
                !territory.TryEvaluateCurrentPosition(
                    out var blockedEvaluation) &&
                !blockedEvaluation.IsValid;
            Debug.Assert(blockedPassed, "無効な縄張り中心への対応", this);
            Check(blockedPassed, "無効な縄張り中心への対応");

            long blockedCount =
                territory.RecalculationCount;

            territory.Refresh();
            territory.GetDistance(Origin);

            bool blockedCachePassed =
                territory.RecalculationCount == blockedCount;
            Debug.Assert(blockedCachePassed, "無効起点の再計算抑制", this);
            Check(blockedCachePassed, "無効起点の再計算抑制");

            stageManager.Map.SetCell(
                Origin,
                MazeCell.CreateFloor());

            bool recoveryPassed =
                territory.Refresh() &&
                territory.GetDistance(Origin) == 0;
            Debug.Assert(recoveryPassed, "通行条件復旧後の再評価", this);
            Check(recoveryPassed, "通行条件復旧後の再評価");

            territory.Dispose();

            bool disposedPassed =
                territory.IsDisposed &&
                !territory.IsValid &&
                !territory.IsDirty &&
                !territory.Refresh() &&
                !territory.TryEvaluate(
                    Origin,
                    out var disposedEvaluation) &&
                !disposedEvaluation.IsValid;
            Debug.Assert(disposedPassed, "破棄後の評価拒否", this);
            Check(disposedPassed, "破棄後の評価拒否");

            // 破棄後にグリッドを変更しても利用可能にならない。
            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            territory.Dispose();

            bool ownershipPassed =
                territory.IsDisposed &&
                !territory.IsDirty &&
                context.IsValid &&
                !parameters.IsDisposed;
            Debug.Assert(ownershipPassed, "重複破棄と外部所有権の維持", this);
            Check(ownershipPassed, "重複破棄と外部所有権の維持");

            // コンテキストが無効化された場合の動作を確認する。
            territory = new MazeEnemyTerritory(context);

            context.Dispose();

            bool contextDisposedPassed =
                !territory.IsValid &&
                !territory.Refresh() &&
                territory.GetDistance(Origin) == -1 &&
                Approximately(
                    territory.GetPreferenceMultiplier(Origin),
                    0f);
            Debug.Assert(contextDisposedPassed, "コンテキスト破棄への対応", this);
            Check(contextDisposedPassed, "コンテキスト破棄への対応");
        }

        /// <summary>
        /// 浮動小数点数が許容誤差以内で一致するか確認する。
        /// </summary>
        /// <param name="actual">実際の値</param>
        /// <param name="expected">期待する値</param>
        /// <returns>許容誤差以内の場合はtrue</returns>
        private bool Approximately(
            float actual,
            float expected)
        {
            return Mathf.Abs(actual - expected) <= Tolerance;
        }

        /// <summary>
        /// テスト環境を破棄する。
        /// </summary>
        private void Cleanup()
        {
            // 依存する側から順番に破棄する。
            territory?.Dispose();
            territory = null;

            context?.Dispose();
            context = null;

            parameters?.Dispose();
            parameters = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);

                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);

                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時にテスト環境を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
